bench_run = function(d) {
  ok = is.finite(d$time) & is.finite(d$dead) & is.finite(d$row_weights) & d$row_weights > 0
  Xf = cbind("(Intercept)" = 1, d$X[ok, , drop = FALSE])
  Y = cbind(time = log(d$time[ok]), status = d$dead[ok])   # survreg's weibull -> extreme-value on log time
  fit = tryCatch(survival::survreg.fit(x = Xf, y = Y, weights = d$row_weights[ok], offset = NULL,
    init = NULL, controlvals = survival::survreg.control(),
    dist = survival::survreg.distributions$extreme, scale = 0, nstrat = 1),
    error = function(e) NULL)
  if (is.null(fit) || is.character(fit)) {
    fit2 = EDI:::weighted_weibull_bootstrap_surrogate_fit(d$time, d$dead, d$X, d$row_weights)
    return(as.numeric(c(fit2$beta_hat, fit2$se)))
  }
  as.numeric(c(fit$coefficients[["treatment"]], sqrt(fit$var["treatment", "treatment"])))
}
